#[cfg(test)]
mod frozen_rescore_once {
    use super::*;
    use serde_json::Value;
fn before(summary: &str, checks: &[Check]) -> Vec<String> {
    let parts = sections(summary);
    let mut out = vec![];
    for check in checks {
        if !parts.iter().any(|(name, _)| check.sections.contains(name)) {
            out.push(format!("missing section {}", check.sections.join("/")));
        }
        let text: String = parts.iter().filter(|(name, _)| check.sections.contains(name)).map(|(_, body)| body.to_lowercase()).collect();
        let place = check.sections.join("/");
        if !check.any.is_empty() && !check.any.iter().any(|w| text.contains(&w.to_lowercase())) {
            out.push(format!("{place} lacks any of {:?}", check.any));
        }
        for w in check.absent.iter().filter(|w| text.contains(&w.to_lowercase())) {
            out.push(format!("{place} has \"{w}\""));
        }
        for item in blocks(&text) {
            let (Block::Bullet(item) | Block::Paragraph(item) | Block::Todo { text: item, .. }) = item else { continue };
            for w in check.absent_items.iter().filter(|w| item.trim().trim_end_matches(['.', '。']).eq_ignore_ascii_case(w)) {
                out.push(format!("{place} has standalone \"{w}\""));
            }
        }
    }
    out
}

    #[test]
    fn rescore_frozen_reports() {
        let root = PathBuf::from("/tmp/boardcast-summary-source-s8jyqbhd");
        let before_cases: Vec<Case> = serde_json::from_slice(&std::fs::read(root.join("before-cases.json")).unwrap()).unwrap();
        let cases: Vec<Case> = serde_json::from_str(include_str!("../../../eval/summary-cases.json")).unwrap();
        let reports: Vec<Value> = serde_json::from_slice(&std::fs::read(root.join("rescore-input.json")).unwrap()).unwrap();
        let mut results = vec![];
        for report in reports {
            let mut answers = vec![];
            for answer in report["report"]["answers"].as_array().unwrap() {
                let id = answer["case"].as_str().unwrap();
                let summary = answer["summary"].as_str().unwrap();
                assert!(!summary.is_empty());
                let old_case = before_cases.iter().find(|c| c.id == id).unwrap();
                let case = cases.iter().find(|c| c.id == id).unwrap();
                let before_failures = before(summary, &old_case.checks);
                let after_failures = failures(summary, &case.checks);
                answers.push(json!({"case":id,"run":answer["run"],"summary":summary,"original_failures":answer["failures"],"before_failures":before_failures,"after_failures":after_failures}));
            }
            let before = answers.iter().filter(|a| a["before_failures"].as_array().unwrap().is_empty()).count();
            let after = answers.iter().filter(|a| a["after_failures"].as_array().unwrap().is_empty()).count();
            assert_eq!(json!(before), report["expected_before"]);
            assert_eq!(json!(after), report["expected_after"]);
            results.push(json!({"name":report["name"],"before_passed":before,"after_passed":after,"total":answers.len(),"answers":answers}));
        }
        std::fs::write(root.join("rescored.json"), serde_json::to_vec_pretty(&results).unwrap()).unwrap();
    }
}
